import csv
import io
import re

def parse_csv(raw_csv: str):
    expected_width = 9
    records = []

    reader = csv.reader(
        io.StringIO(raw_csv),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    try:
        for record in reader:
            if record:
                records.append([str(value) for value in record])
    except csv.Error:
        records = []
        for line in raw_csv.splitlines():
            if line:
                try:
                    records.append(next(csv.reader(
                        [line],
                        delimiter=",",
                        quotechar='"',
                        doublequote=True,
                        strict=False,
                    )))
                except csv.Error:
                    records.append(line.split(","))

    if records:
        records[0][0] = records[0][0].lstrip("\ufeff")

    identifier_pattern = re.compile(
        r"^[A-Za-z_][A-Za-z0-9_]*(?:[ \-]+[A-Za-z0-9_]+)*$"
    )

    def header_score(record):
        if len(record) != expected_width:
            return -1
        score = 0
        seen = set()
        for value in record:
            value = value.strip()
            if value and identifier_pattern.fullmatch(value):
                score += 1
            if value:
                if value.lower() in seen:
                    score -= 1
                seen.add(value.lower())
            if re.search(r"\d{1,4}[/-]\d{1,2}[/-]\d{1,4}", value):
                score -= 2
            if re.search(r"\$\s*\d", value):
                score -= 2
            if re.fullmatch(r"\d{1,2}:\d{2}", value):
                score -= 2
        return score

    header_index = None
    best_score = -1
    for index, record in enumerate(records):
        score = header_score(record)
        if score >= 0 and score > best_score:
            best_score = score
            header_index = index
            if score >= expected_width - 1:
                break

    if header_index is None:
        for index, record in enumerate(records):
            if len(record) == expected_width:
                header_index = index
                break

    if header_index is None:
        if records:
            header_index = 0
            columns = list(records[0])
        else:
            columns = []
        rows = records[header_index + 1:] if records else []
    else:
        columns = list(records[header_index])
        rows = records[header_index + 1:]

    if not columns:
        columns = ["column_%d" % (index + 1) for index in range(expected_width)]

    while len(columns) < expected_width:
        columns.append("column_%d" % (len(columns) + 1))

    maximum_width = max([len(columns)] + [len(row) for row in rows]) if rows else len(columns)

    existing = set(columns)
    while len(columns) < maximum_width:
        base = "column_%d" % (len(columns) + 1)
        name = base
        suffix = 2
        while name in existing:
            name = "%s_%d" % (base, suffix)
            suffix += 1
        columns.append(name)
        existing.add(name)

    normalized_rows = []
    for row in rows:
        if len(row) < len(columns):
            normalized_rows.append(row + [""] * (len(columns) - len(row)))
        else:
            normalized_rows.append(row[:len(columns)])

    return {"columns": columns, "rows": normalized_rows}
